input.content:
import { describe, it, expect } from "vitest";
import { quote } from "./quote.js";

describe("MHPCO Quote", () => {
  it.todo("should compute premium for an empty item list -- 5 G (only processing fee)");

  it.todo("should compute base premium for a plain sword -- 105 G (100 base + 5 fee)");
  it.todo("should compute base premium for a plain amulet -- 65 G (60 base + 5 fee)");
  it.todo("should compute base premium for a plain staff -- 85 G (80 base + 5 fee)");
  it.todo("should compute base premium for a plain potion -- 45 G (40 base + 5 fee)");

  it.todo("should compute base premium for two runes -- 50 G (no building block)");
  it.todo("should compute base premium for three runes -- 60 G (building block of 3 alike components)");
  it.todo("should compute base premium for four runes -- 100 G (no block, block requires exactly 3)");
  it.todo("should compute base premium for seven runes -- 175 G (no block)");

  it.todo("should treat different component types as not alike -- 2 runes + 1 moonstone -> 75 G");
  it.todo("should form two separate blocks for 3 runes + 3 moonstones -- 120 G");

  it.todo("should apply cursed surcharge only to the cursed item, not the policy total -- cursed sword + plain amulet -> 160 G base, +50 G curse");

  it.todo("should apply loyalty discount at exactly 2 years with MHPCO");
  it.todo("should apply high-enchantment surcharge at exactly enchantment 5");
  it.todo("should apply both curse and high-enchantment surcharges together");
  it.todo("should NOT apply high-enchantment surcharge at enchantment 4");

  it.todo("should round premium up in MHPCO's favor -- 197.5 G -> 198 G");
  it.todo("should keep intermediate amounts as fractions and only round the final premium");

  it.todo("should compute newcomer with a cursed sword -- 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
  it.todo("should compute a long-standing customer's second contract -- 160 G (100 + 50 curse + 30 high ench - 20 loyalty + 10 first + -15 follow-up + 5 fee)");
  it.todo("should apply first-insurance surcharge per item regardless of customer history");

  it.todo("should reject quote with unknown item type (e.g. broomstick)");
});

import { describe, it, expect } from "vitest";
import { claim } from "./claim.js";

describe("MHPCO Claim", () => {
  it.todo("should reimburse a regular sword (steel, enchantment 3) with 500 G damage -- 400 G payout (full minus 100 deductible)");
  it.todo("should reimburse damage to a rune (250 G value) with 200 G damage -- 100 G payout (full minus deductible, no special clause)");

  it.todo("should reimburse dragon-material sword with enchantment 9, 1000 G damage -- 400 G payout (50% then deductible)");
  it.todo("should reimburse dragon-material sword with enchantment 5, 800 G damage -- 700 G payout (full then deductible)");
  it.todo("should reimburse steel sword with enchantment 9, 1000 G damage -- 400 G payout (50% then deductible)");
  it.todo("should reimburse dragon-material sword with exactly enchantment 8, 1000 G damage -- 400 G payout (high enchantment then deductible)");

  it.todo("should apply deductible once per damaged item -- dragon attack on sword (500) and amulet (300) -> 600 G payout");

  it.todo("should round payout down in MHPCO's favor -- 350.5 G -> 350 G");

  it.todo("should compute insurance sum for two swords -- 2000 G, cap 4000 G");
  it.todo("should treat each damages entry as separate damage with its own deductible");
  it.todo("should reject claim with more damages of a type than policy covers");

  it.todo("should compute insurance sum for sword + amulet -- 1600 G, cap 3200 G");
  it.todo("should base cap on unmodified insurance value for a cursed sword -- 1000 G value, cap 2000 G");
  it.todo("should base insurance sum on items, block discount affects premium only -- sword + 3 runes -> 1750 G");
  it.todo("should exhaust cap across successive claims -- first 1500 G claim -> 1400 payout (600 remaining), second -> 600 payout (0 remaining)");

  it.todo("should reject claim referencing damage to an item not in the policy");
  it.todo("should reject claim with negative damage amount (-200)");
});

