input.newString:
const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

export function quote(_customer: Customer, items: Item[]): number {
  const components: Record<string, number> = {};
  let mainPremium = 0;

  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      components[item.type] = (components[item.type] ?? 0) + 1;
    } else {
      mainPremium += BASE_PREMIUM[item.type];
    }
  }

  let componentPremium = 0;
  for (const type of Object.keys(components)) {
    const count = components[type];
    componentPremium += count === 3 ? 60 : count * 25;
  }

  return mainPremium + componentPremium + 5;
}

