import { describe, it, expect } from "vitest";
import { basePremium, quote } from "./quote.js";

describe("MHPCO base premium", () => {
  it("should return 0 for empty item list", () => {
    expect(basePremium([])).toBe(0);
  });

  it("should return 100 G for a sword", () => {
    expect(basePremium([{ type: "sword" }])).toBe(100);
  });
  it("should return 60 G for an amulet", () => {
    expect(basePremium([{ type: "amulet" }])).toBe(60);
  });
  it("should return 80 G for a staff", () => {
    expect(basePremium([{ type: "staff" }])).toBe(80);
  });
  it("should return 40 G for a potion", () => {
    expect(basePremium([{ type: "potion" }])).toBe(40);
  });

  it("should return 50 G for two runes (no building block)", () => {
    expect(basePremium([{ type: "rune" }, { type: "rune" }])).toBe(50);
  });
  it("should return 60 G for three runes (building block of 3)", () => {
    expect(basePremium([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(60);
  });
  it("should return 100 G for four runes (no block, block requires exactly 3)", () => {
    expect(basePremium([{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(100);
  });
  it("should return 175 G for seven runes (no block)", () => {
    const items = new Array(7).fill({ type: "rune" });
    expect(basePremium(items)).toBe(175);
  });

  it("should treat different component types as not alike -- 2 runes + 1 moonstone -> 75 G", () => {
    expect(basePremium([{ type: "rune" }, { type: "rune" }, { type: "moonstone" }])).toBe(75);
  });
  it("should form two separate blocks for 3 runes + 3 moonstones -- 120 G", () => {
    const items = [
      { type: "rune" }, { type: "rune" }, { type: "rune" },
      { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
    ];
    expect(basePremium(items)).toBe(120);
  });
});

describe("MHPCO quote (full premium)", () => {
  it("should return 5 G (only processing fee) for empty item list", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [], 1)).toBe(5);
  });

  it("should apply cursed surcharge only to the cursed item -- cursed sword + plain amulet -> 231 G", () => {
    const items = [{ type: "sword", cursed: true }, { type: "amulet" }];
    expect(quote({ yearsWithMHPCO: 0 }, items, 1)).toBe(231);
  });

  it("should apply loyalty discount at exactly 2 years -- plain sword -> 95 G", () => {
    expect(quote({ yearsWithMHPCO: 2 }, [{ type: "sword" }], 1)).toBe(95);
  });
  it("should NOT apply loyalty discount at 1 year -- plain sword -> 115 G", () => {
    expect(quote({ yearsWithMHPCO: 1 }, [{ type: "sword" }], 1)).toBe(115);
  });

  it("should apply high-enchantment surcharge at exactly enchantment 5 -- sword -> 145 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5 }], 1)).toBe(145);
  });
  it("should apply both curse and high-enchantment surcharges -- cursed sword ench 5 -> 195 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5, cursed: true }], 1)).toBe(195);
  });
  it("should NOT apply high-enchantment surcharge at enchantment 4 -- sword -> 115 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 4 }], 1)).toBe(115);
  });

  it("should round premium up in MHPCO's favor -- 7 runes -> 198 G (197.5 rounded up)", () => {
    const items = new Array(7).fill({ type: "rune" });
    expect(quote({ yearsWithMHPCO: 0 }, items, 1)).toBe(198);
  });

  it("should compute newcomer with a cursed sword -> 165 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true, enchantment: 3 }], 1)).toBe(165);
  });

  it("should compute a long-standing customer's second contract -> 160 G", () => {
    expect(quote({ yearsWithMHPCO: 3 }, [{ type: "sword", cursed: true, enchantment: 7 }], 2)).toBe(160);
  });

  it("should apply first-insurance surcharge per item regardless of customer history", () => {
    expect(quote({ yearsWithMHPCO: 3 }, [{ type: "sword", cursed: true, enchantment: 7 }], 2)).toBe(160);
  });
});

import { describe, it, expect } from "vitest";
import { insuranceSum, processClaim, type PolicyItem } from "./claim.js";

const sword: PolicyItem = { type: "sword" };

describe("MHPCO insurance sum", () => {
  it("should sum insurance values for a sword (1000) and amulet (600) -> 1600 G", () => {
    expect(insuranceSum([{ type: "sword" }, { type: "amulet" }])).toBe(1600);
  });
  it("should sum two swords -> 2000 G", () => {
    expect(insuranceSum([{ type: "sword" }, { type: "sword" }])).toBe(2000);
  });
  it("should base insurance sum on unmodified values -- cursed sword -> 1000 G", () => {
    expect(insuranceSum([{ type: "sword", cursed: true }])).toBe(1000);
  });
  it("should count block components at full value -- sword + 3 runes -> 1750 G", () => {
    expect(insuranceSum([{ type: "sword" }, { type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(1750);
  });
});

describe("MHPCO claim (payout)", () => {
  it("should reimburse a regular sword (steel, enchantment 3) with 500 G damage -> 400 G", () => {
    const r = processClaim([{ type: "sword", material: "steel", enchantment: 3 }], 2000, [
      { itemType: "sword", amount: 500 },
    ]);
    expect(r.payout).toBe(400);
    expect(r.remainingCap).toBe(1600);
  });

  it("should reimburse damage to a rune with 200 G damage -> 100 G", () => {
    const r = processClaim([{ type: "rune" }], 500, [{ itemType: "rune", amount: 200 }]);
    expect(r.payout).toBe(100);
  });

  it("should reimburse dragon sword enchantment 9 with 1000 G damage -> 400 G (50% then deductible)", () => {
    const r = processClaim([{ type: "sword", material: "dragon", enchantment: 9 }], 2000, [
      { itemType: "sword", amount: 1000 },
    ]);
    expect(r.payout).toBe(400);
  });

  it("should reimburse dragon sword enchantment 5 with 800 G damage -> 700 G (full then deductible)", () => {
    const r = processClaim([{ type: "sword", material: "dragon", enchantment: 5 }], 2000, [
      { itemType: "sword", amount: 800 },
    ]);
    expect(r.payout).toBe(700);
  });

  it("should reimburse steel sword enchantment 9 with 1000 G damage -> 400 G (50% then deductible)", () => {
    const r = processClaim([{ type: "sword", material: "steel", enchantment: 9 }], 2000, [
      { itemType: "sword", amount: 1000 },
    ]);
    expect(r.payout).toBe(400);
  });

  it("should reimburse dragon sword enchantment exactly 8 with 1000 G damage -> 400 G", () => {
    const r = processClaim([{ type: "sword", material: "dragon", enchantment: 8 }], 2000, [
      { itemType: "sword", amount: 1000 },
    ]);
    expect(r.payout).toBe(400);
  });

  it("should apply deductible once per damaged item -- sword 500 + amulet 300 -> 600 G", () => {
    const r = processClaim([{ type: "sword" }, { type: "amulet" }], 5000, [
      { itemType: "sword", amount: 500 },
      { itemType: "amulet", amount: 300 },
    ]);
    expect(r.payout).toBe(600);
  });

  it("should round payout down in MHPCO's favor -- enchantment 9 steel sword damage 901 -> 350 G", () => {
    const r = processClaim([{ type: "sword", material: "steel", enchantment: 9 }], 2000, [
      { itemType: "sword", amount: 901 },
    ]);
    expect(r.payout).toBe(350);
  });

  it("should treat each damage entry as separate damage with its own deductible -- two swords -> 800 G", () => {
    const r = processClaim([{ type: "sword" }, { type: "sword" }], 4000, [
      { itemType: "sword", amount: 500 },
      { itemType: "sword", amount: 500 },
    ]);
    expect(r.payout).toBe(800);
  });

  it("should exhaust cap across successive claims -- 1500 then 1500 on a sword", () => {
    const policy = [{ type: "sword", material: "steel", enchantment: 3 }];
    const first = processClaim(policy, 2000, [{ itemType: "sword", amount: 1500 }]);
    expect(first.payout).toBe(1400);
    expect(first.remainingCap).toBe(600);
    const second = processClaim(policy, first.remainingCap, [{ itemType: "sword", amount: 1500 }]);
    expect(second.payout).toBe(600);
    expect(second.remainingCap).toBe(0);
  });

  it("should reject claim with more damages of a type than policy covers", () => {
    expect(() =>
      processClaim([{ type: "sword" }], 2000, [
        { itemType: "sword", amount: 500 },
        { itemType: "sword", amount: 500 },
      ]),
    ).toThrow();
  });

  it("should reject claim referencing damage to an item not in the policy", () => {
    expect(() =>
      processClaim([{ type: "sword" }], 2000, [{ itemType: "amulet", amount: 200 }]),
    ).toThrow();
  });

  it("should reject claim with negative damage amount", () => {
    expect(() =>
      processClaim([{ type: "sword" }], 2000, [{ itemType: "sword", amount: -200 }]),
    ).toThrow();
  });
});

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

export function basePremium(items: Item[]): number {
  const components: Record<string, number> = {};
  let mainPremium = 0;

  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      components[item.type] = (components[item.type] ?? 0) + 1;
    } else {
      mainPremium += BASE_PREMIUM[item.type];
    }
  }

  let componentPremium = 0;
  for (const type of Object.keys(components)) {
    const count = components[type];
    componentPremium += count === 3 ? 60 : count * 25;
  }

  return mainPremium + componentPremium;
}

export function quote(customer: Customer, items: Item[], contractNumber: number): number {
  const policyBase = basePremium(items);

  let itemSurcharge = 0;
  for (const item of items) {
    if (item.cursed) itemSurcharge += 0.5 * BASE_PREMIUM[item.type];
    if ((item.enchantment ?? 0) >= 5) itemSurcharge += 0.3 * BASE_PREMIUM[item.type];
  }

  let policyModifier = 0;
  policyModifier += 0.1 * policyBase;
  if (customer.yearsWithMHPCO >= 2) policyModifier -= 0.2 * policyBase;
  if (contractNumber >= 2) policyModifier -= 0.15 * policyBase;

  const total = policyBase + itemSurcharge + policyModifier + 5;
  return Math.ceil(total);
}

export interface PolicyItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const INSURANCE_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

export function insuranceSum(items: PolicyItem[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
}

export function processClaim(
  items: PolicyItem[],
  remainingCap: number,
  damages: Damage[],
): ClaimResult {
  const counts: Record<string, number> = {};
  for (const item of items) {
    counts[item.type] = (counts[item.type] ?? 0) + 1;
  }

  for (const damage of damages) {
    if (damage.amount < 0) {
      throw new Error(`negative damage amount: ${damage.amount}`);
    }
    const covered = counts[damage.itemType] ?? 0;
    if (covered === 0) {
      throw new Error(`item not covered by policy: ${damage.itemType}`);
    }
    counts[damage.itemType] = covered - 1;
  }

  let raw = 0;
  for (const damage of damages) {
    const item = items.find((i) => i.type === damage.itemType)!;
    const rate = (item.enchantment ?? 0) >= 8 ? 0.5 : 1.0;
    raw += Math.max(0, damage.amount * rate - 100);
  }

  const payout = Math.min(Math.floor(raw), remainingCap);
  return { payout, remainingCap: remainingCap - payout };
}

import { quote, type Item as QuoteItem } from "./quote.js";
import { insuranceSum, processClaim, type PolicyItem } from "./claim.js";

interface CustomerInput {
  yearsWithMHPCO: number;
}

interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: { itemType: string; amount: number }[];
  };
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  customer: CustomerInput;
  steps: Step[];
}

interface PolicyState {
  items: PolicyItem[];
  remainingCap: number;
}

function main(): void {
  let input = "";
  process.stdin.setEncoding("utf8");
  process.stdin.on("data", (chunk) => {
    input += chunk;
  });
  process.stdin.on("end", () => {
    try {
      const scenario = JSON.parse(input) as Scenario;
      const results = run(scenario);
      process.stdout.write(JSON.stringify({ results }) + "\n");
    } catch (err) {
      process.stderr.write(String((err as Error).message) + "\n");
      process.exitCode = 1;
    }
  });
}

function run(scenario: Scenario): unknown[] {
  const policies: PolicyState[] = [];
  const results: unknown[] = [];
  let contractNumber = 0;

  for (const step of scenario.steps) {
    if (step.op === "quote") {
      contractNumber += 1;
      const items: Item[] = step.items;
      const premium = quote(scenario.customer, step.items, contractNumber);
      const policyItems = step.items.map((i) => ({ ...i }));
      const sum = insuranceSum(policyItems);
      policies.push({ items: policyItems, remainingCap: sum * 2 });
      results.push({ premium });
    } else {
      const policy = policies[step.policy];
      const r = processClaim(policy.items, policy.remainingCap, step.incident.damages);
      policy.remainingCap = r.remainingCap;
      results.push({ payout: r.payout, remainingCap: r.remainingCap });
    }
  }

  return results;
}

main();

