const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_BLOCK_COUNT = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
const COMPONENT_UNIT_PREMIUM = 25;

const CURSED_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const FIRST_INSURANCE_RATE = 0.1;
const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_THRESHOLD = 2;
const FOLLOW_UP_DISCOUNT = 0.15;
const PROCESSING_FEE = 5;

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export function basePremium(items: Item[]): number {
  const components: Record<string, number> = {};
  let mainPremium = 0;

  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      components[item.type] = (components[item.type] ?? 0) + 1;
    } else {
      mainPremium += BASE_PREMIUM[item.type];
    }
  }

  let componentPremium = 0;
  for (const type of Object.keys(components)) {
    const count = components[type];
    componentPremium +=
      count === COMPONENT_BLOCK_COUNT ? COMPONENT_BLOCK_PREMIUM : count * COMPONENT_UNIT_PREMIUM;
  }

  return mainPremium + componentPremium;
}

export function quote(customer: Customer, items: Item[], contractNumber: number): number {
  const policyBase = basePremium(items);
  const itemSurcharge = computeItemSurcharge(items);
  const policyModifier = computePolicyModifier(customer.yearsWithMHPCO, contractNumber, policyBase);

  return Math.ceil(policyBase + itemSurcharge + policyModifier + PROCESSING_FEE);
}

function computeItemSurcharge(items: Item[]): number {
  let surcharge = 0;
  for (const item of items) {
    if (item.cursed) surcharge += CURSED_SURCHARGE * BASE_PREMIUM[item.type];
    if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
      surcharge += HIGH_ENCHANTMENT_SURCHARGE * BASE_PREMIUM[item.type];
    }
  }
  return surcharge;
}

function computePolicyModifier(years: number, contractNumber: number, policyBase: number): number {
  let modifier = FIRST_INSURANCE_RATE * policyBase;
  if (years >= LOYALTY_THRESHOLD) modifier -= LOYALTY_DISCOUNT * policyBase;
  if (contractNumber >= 2) modifier -= FOLLOW_UP_DISCOUNT * policyBase;
  return modifier;
}

const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 8;

const INSURANCE_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

export interface PolicyItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export function insuranceSum(items: PolicyItem[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
}

export function processClaim(
  items: PolicyItem[],
  remainingCap: number,
  damages: Damage[],
): ClaimResult {
  validateDamages(items, damages);

  const raw = damages.reduce((sum, damage) => {
    const item = items.find((i) => i.type === damage.itemType)!;
    return sum + reimbursement(item, damage.amount);
  }, 0);

  const payout = Math.min(Math.floor(raw), remainingCap);
  return { payout, remainingCap: remainingCap - payout };
}

function validateDamages(items: PolicyItem[], damages: Damage[]): void {
  const remaining: Record<string, number> = {};
  for (const item of items) {
    remaining[item.type] = (remaining[item.type] ?? 0) + 1;
  }

  for (const damage of damages) {
    if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
    const count = remaining[damage.itemType] ?? 0;
    if (count === 0) throw new Error(`item not covered by policy: ${damage.itemType}`);
    remaining[damage.itemType] = count - 1;
  }
}

function reimbursement(item: PolicyItem, amount: number): number {
  const rate =
    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
      ? HIGH_ENCHANTMENT_REIMBURSEMENT
      : 1;
  return Math.max(0, amount * rate - DEDUCTIBLE);
}

